dashboard.definition:
{
  "title": "Réplication et synchronisation AD",
  "description": "État de la réplication Active Directory entre contrôleurs de domaine : état de chaque lien (dernier succès, retard, dernier résultat) depuis MSAD:NT6:Replication, événements Directory Service et DFSR liés à la réplication (KCC, objets lingering, durée de vie tombstone, échecs DNS, USN rollback), audit de début/fin de synchronisation et échecs Kerberos liés à l'horloge.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Période",
      "options": {
        "token": "global_time",
        "defaultValue": "-7d@h,now"
      }
    }
  },
  "defaults": {},
  "visualizations": {
    "viz_general_sum": {
      "type": "splunk.table",
      "title": "Synthèse par tête d'infra",
      "description": "Un onglet par domaine / forêt AD (numérotés par ordre alphabétique du domaine ; lookups/adx_infra_heads.csv permet de fixer numéro et libellé). Cliquez sur un onglet « Tête n » pour le détail.",
      "dataSources": {
        "primary": "ds_general_sum"
      },
      "options": {
        "count": 8,
        "wrap": true
      }
    },
    "viz_general_map": {
      "type": "splunk.table",
      "title": "Correspondance onglets / domaines / DC",
      "dataSources": {
        "primary": "ds_general_map"
      },
      "options": {
        "count": 8,
        "wrap": true
      }
    },
    "viz_1_general": {
      "type": "splunk.singlevalue",
      "title": "DC qui remontent l'état de réplication",
      "dataSources": {
        "primary": "ds_1_general"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_repl_data`",
            "earliest": "-30m",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_2_general": {
      "type": "splunk.singlevalue",
      "title": "Liens de réplication en échec",
      "dataSources": {
        "primary": "ds_2_general"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_repl_links` | where last_result!=\"0\" | table dc partner naming_context last_result last_success_epoch lag_min",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_3_general": {
      "type": "splunk.singlevalue",
      "title": "Délai max depuis le dernier succès (min)",
      "dataSources": {
        "primary": "ds_3_general"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 60
          },
          {
            "value": "#FFC300",
            "from": 60,
            "to": 240
          },
          {
            "value": "#B0413E",
            "from": 240
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_repl_links` | table dc partner naming_context last_result last_success_epoch lag_min",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_4_general": {
      "type": "splunk.singlevalue",
      "title": "Événements d'erreur de réplication",
      "dataSources": {
        "primary": "ds_4_general"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 10
          },
          {
            "value": "#B0413E",
            "from": 10
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_ds_events` EventCode IN (1308,1311,1388,1566,1865,1925,1988,2042,2087,2088,2095,2213,4012)",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_5_general": {
      "type": "splunk.singlevalue",
      "title": "Événements critiques (objets lingering, tombstone, USN rollback)",
      "dataSources": {
        "primary": "ds_5_general"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_ds_events` EventCode IN (1388,1988,2042,2095,4012)",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_6_general": {
      "type": "splunk.singlevalue",
      "title": "Minutes depuis le dernier événement de réplication",
      "dataSources": {
        "primary": "ds_6_general"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 30
          },
          {
            "value": "#B0413E",
            "from": 30
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_repl_data` | stats max(_time) as t | eval m=round((now()-t)/60,0) | fields m",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_7_general": {
      "type": "splunk.table",
      "title": "Liens de réplication - état actuel",
      "dataSources": {
        "primary": "ds_7_general"
      },
      "options": {
        "count": 15,
        "wrap": true,
        "columnFormat": {
          "Statut": {
            "rowBackgroundColors": "> table | seriesByName(\"Statut\") | matchValue(col0ColorConfig)"
          }
        }
      },
      "description": "dc = DC qui reçoit les changements, partner = source de réplication (src_host). Source : MSAD:NT6:Replication (LastSuccessfulSync / LastAttemptedSync / Result ; Result 0 = succès). EN RETARD = aucune synchronisation réussie depuis plus de 4 heures.",
      "context": {
        "col0ColorConfig": [
          {
            "match": "OK",
            "value": "#65A637"
          },
          {
            "match": "EN RETARD",
            "value": "#F8BE34"
          },
          {
            "match": "EN ÉCHEC",
            "value": "#B0413E"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_repl_links` | eval last_success=strftime(last_success_epoch,\"%Y-%m-%d %H:%M\"), last_attempt=strftime(last_attempt_epoch,\"%Y-%m-%d %H:%M\"), status=case(last_result!=\"0\",\"EN ÉCHEC\", lag_min>240,\"EN RETARD\", true(),\"OK\") | sort - status, - lag_min | table dc partner naming_context transport status last_success last_attempt lag_min last_result | rename dc as \"DC\", partner as \"Partenaire\", naming_context as \"Partition\", transport as \"Transport\", status as \"Statut\", last_success as \"Dernier succès\", last_attempt as \"Dernière tentative\", lag_min as \"Retard (min)\", last_result as \"Dernier résultat\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_8_general": {
      "type": "splunk.column",
      "title": "Événements de réplication en échec par DC",
      "dataSources": {
        "primary": "ds_8_general"
      },
      "options": {
        "legendDisplay": "bottom",
        "stackMode": "stacked"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_repl_data` | where Result!=\"0\" | timechart span=1h count by host",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_9_general": {
      "type": "splunk.column",
      "title": "Événements liés à la réplication dans le temps",
      "dataSources": {
        "primary": "ds_9_general"
      },
      "options": {
        "legendDisplay": "bottom",
        "stackMode": "stacked"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_ds_events` EventCode IN (1308,1311,1388,1566,1865,1925,1988,2042,2087,2088,2095,2213,4012) | timechart count by EventCode",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_10_general": {
      "type": "splunk.table",
      "title": "Événements de réplication Directory Service / DFSR",
      "dataSources": {
        "primary": "ds_10_general"
      },
      "options": {
        "count": 10,
        "wrap": true,
        "columnFormat": {
          "Gravité": {
            "rowBackgroundColors": "> table | seriesByName(\"Gravité\") | matchValue(col0ColorConfig)"
          }
        }
      },
      "context": {
        "col0ColorConfig": [
          {
            "match": "critique",
            "value": "#B0413E"
          },
          {
            "match": "élevée",
            "value": "#F1813F"
          },
          {
            "match": "moyenne",
            "value": "#F8BE34"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_ds_events` EventCode IN (1308,1311,1388,1566,1865,1925,1988,2042,2087,2088,2095,2213,4012) | rename EventCode as event_id | lookup adx_replication_events event_id OUTPUT description severity | eval dc=coalesce(Computer, ComputerName, host), message=substr(coalesce(Message, _raw),1,300) | sort - _time | table _time dc event_id severity description message | rename _time as \"Heure\", dc as \"DC\", event_id as \"ID événement\", severity as \"Gravité\", description as \"Description\", message as \"Message\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_11_general": {
      "type": "splunk.table",
      "title": "Erreurs de réplication par DC et par événement",
      "dataSources": {
        "primary": "ds_11_general"
      },
      "options": {
        "count": 10,
        "wrap": true
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_ds_events` EventCode IN (1308,1311,1388,1566,1865,1925,1988,2042,2087,2088,2095,2213,4012) | rename EventCode as event_id | lookup adx_replication_events event_id OUTPUT description | eval dc=coalesce(Computer, ComputerName, host) | stats count, latest(_time) as last by dc event_id description | eval last=strftime(last,\"%Y-%m-%d %H:%M\") | sort - count | table dc event_id description count last | rename dc as \"DC\", event_id as \"ID événement\", description as \"Description\", count as \"Nombre\", last as \"Dernière occurrence\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_12_general": {
      "type": "splunk.table",
      "title": "Sécurité 4932/4933 : début/fin de synchronisation de réplica",
      "dataSources": {
        "primary": "ds_12_general"
      },
      "options": {
        "count": 8,
        "wrap": true
      },
      "description": "Nécessite la stratégie d'audit « Audit Detailed Directory Service Replication » (événements Sécurité 4932/4933).",
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` (EventCode=4932 OR EventCode=4933) | eval dc=coalesce(Computer, ComputerName, host), status_code=coalesce(Status_Code, StatusCode, Status), naming_context=coalesce(Naming_Context, NamingContext), source_dra=coalesce(Source_DRA, SourceDRA) | stats count, sum(eval(if(EventCode=4933 AND status_code!=\"0\",1,0))) as failed_syncs by dc naming_context | sort - failed_syncs | table dc naming_context count failed_syncs | rename dc as \"DC\", naming_context as \"Partition\", count as \"Nombre\", failed_syncs as \"Synchros en échec\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_13_general": {
      "type": "splunk.table",
      "title": "Échecs Kerberos par décalage d'horloge (événement 4771, code 0x25) - synchronisation horaire",
      "dataSources": {
        "primary": "ds_13_general"
      },
      "options": {
        "count": 8,
        "wrap": true
      },
      "description": "Clients dont l'horloge dérive de plus de 5 minutes par rapport au DC : effet typique d'une synchronisation horaire AD défaillante.",
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_security_events` EventCode=4771 (Failure_Code=0x25 OR Result_Code=0x25) | eval client=coalesce(IpAddress, Client_Address, src_ip), user=coalesce(TargetUserName, Account_Name) | stats count, latest(_time) as last by client user | eval last=strftime(last,\"%Y-%m-%d %H:%M\") | sort - count | table client user count last | rename client as \"Client\", user as \"Utilisateur\", count as \"Nombre\", last as \"Dernière occurrence\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_h1_banner": {
      "type": "splunk.singlevalue",
      "title": "Tête d'infra 1 - domaine / forêt AD",
      "dataSources": {
        "primary": "ds_h1_banner"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 28
      }
    },
    "viz_1_h1": {
      "type": "splunk.singlevalue",
      "title": "DC qui remontent l'état de réplication",
      "dataSources": {
        "primary": "ds_1_h1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_repl_data` `adx_head_filter(host,1)`",
            "earliest": "-30m",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_2_h1": {
      "type": "splunk.singlevalue",
      "title": "Liens de réplication en échec",
      "dataSources": {
        "primary": "ds_2_h1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_repl_links` `adx_head_filter(dc,1)` | where last_result!=\"0\" | table dc partner naming_context last_result last_success_epoch lag_min",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_3_h1": {
      "type": "splunk.singlevalue",
      "title": "Délai max depuis le dernier succès (min)",
      "dataSources": {
        "primary": "ds_3_h1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 60
          },
          {
            "value": "#FFC300",
            "from": 60,
            "to": 240
          },
          {
            "value": "#B0413E",
            "from": 240
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_repl_links` `adx_head_filter(dc,1)` | table dc partner naming_context last_result last_success_epoch lag_min",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_4_h1": {
      "type": "splunk.singlevalue",
      "title": "Événements d'erreur de réplication",
      "dataSources": {
        "primary": "ds_4_h1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 10
          },
          {
            "value": "#B0413E",
            "from": 10
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_ds_events` EventCode IN (1308,1311,1388,1566,1865,1925,1988,2042,2087,2088,2095,2213,4012) `adx_head_filter(host,1)`",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_5_h1": {
      "type": "splunk.singlevalue",
      "title": "Événements critiques (objets lingering, tombstone, USN rollback)",
      "dataSources": {
        "primary": "ds_5_h1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_ds_events` EventCode IN (1388,1988,2042,2095,4012) `adx_head_filter(host,1)`",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_6_h1": {
      "type": "splunk.singlevalue",
      "title": "Minutes depuis le dernier événement de réplication",
      "dataSources": {
        "primary": "ds_6_h1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 30
          },
          {
            "value": "#B0413E",
            "from": 30
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_repl_data` `adx_head_filter(host,1)` | stats max(_time) as t | eval m=round((now()-t)/60,0) | fields m",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_7_h1": {
      "type": "splunk.table",
      "title": "Liens de réplication - état actuel",
      "dataSources": {
        "primary": "ds_7_h1"
      },
      "options": {
        "count": 15,
        "wrap": true,
        "columnFormat": {
          "Statut": {
            "rowBackgroundColors": "> table | seriesByName(\"Statut\") | matchValue(col0ColorConfig)"
          }
        }
      },
      "description": "dc = DC qui reçoit les changements, partner = source de réplication (src_host). Source : MSAD:NT6:Replication (LastSuccessfulSync / LastAttemptedSync / Result ; Result 0 = succès). EN RETARD = aucune synchronisation réussie depuis plus de 4 heures.",
      "context": {
        "col0ColorConfig": [
          {
            "match": "OK",
            "value": "#65A637"
          },
          {
            "match": "EN RETARD",
            "value": "#F8BE34"
          },
          {
            "match": "EN ÉCHEC",
            "value": "#B0413E"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_repl_links` `adx_head_filter(dc,1)` | eval last_success=strftime(last_success_epoch,\"%Y-%m-%d %H:%M\"), last_attempt=strftime(last_attempt_epoch,\"%Y-%m-%d %H:%M\"), status=case(last_result!=\"0\",\"EN ÉCHEC\", lag_min>240,\"EN RETARD\", true(),\"OK\") | sort - status, - lag_min | table dc partner naming_context transport status last_success last_attempt lag_min last_result | rename dc as \"DC\", partner as \"Partenaire\", naming_context as \"Partition\", transport as \"Transport\", status as \"Statut\", last_success as \"Dernier succès\", last_attempt as \"Dernière tentative\", lag_min as \"Retard (min)\", last_result as \"Dernier résultat\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
