          "options": {
            "query": "`adx_security_events` (EventCode=4932 OR EventCode=4933) `adx_head_filter(host,3)` | eval dc=coalesce(Computer, ComputerName, host), status_code=coalesce(Status_Code, StatusCode, Status), naming_context=coalesce(Naming_Context, NamingContext), source_dra=coalesce(Source_DRA, SourceDRA) | stats count, sum(eval(if(EventCode=4933 AND status_code!=\"0\",1,0))) as failed_syncs by dc naming_context | sort - failed_syncs | table dc naming_context count failed_syncs | rename dc as \"DC\", naming_context as \"Partition\", count as \"Nombre\", failed_syncs as \"Synchros en échec\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
