    "viz_7_h5": {
      "type": "splunk.table",
      "title": "Liens de réplication - état actuel",
      "dataSources": {
        "primary": "ds_7_h5"
      },
      "options": {
        "count": 15,
        "wrap": true,
        "columnFormat": {
          "Statut": {
            "rowBackgroundColors": "> table | seriesByName(\"Statut\") | matchValue(col0ColorConfig)"
          }
        }
      },
      "description": "dc = DC qui reçoit les changements, partner = source de réplication (src_host). Source : MSAD:NT6:Replication (LastSuccessfulSync / LastAttemptedSync / Result ; Result 0 = succès). EN RETARD = aucune synchronisation réussie depuis plus de 4 heures.",
      "context": {
        "col0ColorConfig": [
          {
            "match": "OK",
            "value": "#65A637"
          },
          {
            "match": "EN RETARD",
            "value": "#F8BE34"
          },
          {
            "match": "EN ÉCHEC",
            "value": "#B0413E"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_repl_links` `adx_head_filter(dc,5)` | eval last_success=strftime(last_success_epoch,\"%Y-%m-%d %H:%M\"), last_attempt=strftime(last_attempt_epoch,\"%Y-%m-%d %H:%M\"), status=case(last_result!=\"0\",\"EN ÉCHEC\", lag_min>240,\"EN RETARD\", true(),\"OK\") | sort - status, - lag_min | table dc partner naming_context transport status last_success last_attempt lag_min last_result | rename dc as \"DC\", partner as \"Partenaire\", naming_context as \"Partition\", transport as \"Transport\", status as \"Statut\", last_success as \"Dernier succès\", last_attempt as \"Dernière tentative\", lag_min as \"Retard (min)\", last_result as \"Dernier résultat\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
